/*
* ESP-NOW Sender — Board 1
* Sends a counter to Board 2 every second
* Green LED on D2 blinks on each send
*/

#include <esp_now.h>
#include <WiFi.h>

// Receiver MAC address (Board 2)
uint8_t receiverMAC[] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};

esp_now_peer_info_t peerInfo;

// Data structure to send
typedef struct {
  int counter;
  float temperature;
} DataPacket;

DataPacket myData;
int sendCount = 0;

// Callback when data is sent
void OnDataSent(const uint8_t *mac, esp_now_send_status_t status) {
  if (status == ESP_NOW_SEND_SUCCESS) {
    Serial.println("Data sent OK!");
  } else {
    Serial.println("Send failed!");
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

// Initialize WiFi in station mode
  WiFi.mode(WIFI_STA);
  Serial.print("Sender MAC: ");
  Serial.println(WiFi.macAddress());

// Initialize ESP-NOW
  esp_now_init();
  esp_now_register_send_cb(OnDataSent);

// Configure peer
  memcpy(peerInfo.peer_addr, receiverMAC, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;
  esp_now_add_peer(&peerInfo);

  Serial.println("ESP-NOW Sender ready!");
}

void loop() {
  sendCount++;
  myData.counter = sendCount;
  myData.temperature = 22.5 + (sendCount % 10) * 0.5;

// Blink LED on send
  digitalWrite(2, HIGH);

// Send data
  esp_now_send(receiverMAC, (uint8_t *)&myData, sizeof(myData));

  Serial.print("Sent #");
  Serial.print(sendCount);
  Serial.print(" temp=");
  Serial.println(myData.temperature);

  digitalWrite(2, LOW);
  delay(1000);
}

