/*
 * ESP-NOW Receiver — Board 2
 * Receives data from Board 1 (Sender)
 * Blue LED on D2 blinks on each receive
 */

#include <esp_now.h>
#include <WiFi.h>

// Data structure to receive
typedef struct {
  int counter;
  float temperature;
} DataPacket;

DataPacket incomingData;

// Callback when data is received
void OnDataRecv(const uint8_t *mac, const uint8_t *data, int len) {
  memcpy(&incomingData, data, sizeof(incomingData));

  Serial.print("Received #");
  Serial.print(incomingData.counter);
  Serial.print(" temp=");
  Serial.println(incomingData.temperature);

  // Blink LED on receive
  digitalWrite(2, HIGH);
  delay(50);
  digitalWrite(2, LOW);
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  // Initialize WiFi in station mode
  WiFi.mode(WIFI_STA);
  Serial.print("Receiver MAC: ");
  Serial.println(WiFi.macAddress());

  // Initialize ESP-NOW
  esp_now_init();
  esp_now_register_recv_cb(OnDataRecv);

  Serial.println("ESP-NOW Receiver ready - waiting for data...");
}

void loop() {
  delay(100);
}
